here = os.path.dirname(os.path.abspath(__file__))
files = []
for i, u in enumerate([x for x in URLS.split() if x.startswith("http")], 1):
    p = os.path.join(here, f"h{i:02d}.jpg")
    try:
        req = urllib.request.Request(u, headers={"User-Agent": "Mozilla/5.0"})
        open(p, "wb").write(urllib.request.urlopen(req, timeout=30).read())
        files.append(p)
    except Exception as e:
        print("fail", i, e)

T, cols = 260, 6
rows = (len(files) + cols - 1) // cols
S = Image.new("RGB", (cols * T, rows * (T + 18)), "white")
d = ImageDraw.Draw(S)
for i, f in enumerate(files):
    try:
        im = Image.open(f).convert("RGB"); im.thumbnail((T, T))
    except Exception:
        continue
    x, y = (i % cols) * T, (i // cols) * (T + 18)
    S.paste(im, (x, y)); d.text((x + 4, y + T + 2), os.path.basename(f), fill="black")
S.save(os.path.join(here, "sheet.jpg"))
print("ok", len(files))
